//! Finding, creating, loading and watching the config file.
//!
//! The format is niri's, parsed by niri's own `niri-config` crate. What is specific to ElaraWM
//! is where the file lives, what a fresh one contains, and which sections have no effect.

use std::fs;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use niri_config::Config;

/// What a new config file contains: niri's default config, adjusted for macOS.
///
/// Generated by `tools/gen-elara-default-config.py`.
pub const DEFAULT_CONFIG: &str = include_str!("../../../resources/elara-default-config.kdl");

/// Returns the built-in default config.
pub fn default_config() -> Config {
    Config::parse_mem(DEFAULT_CONFIG).expect("the built-in default config must parse")
}

/// Returns where the config is read from when no path is given: `~/.config/elara/config.kdl`.
///
/// This is deliberately not `~/Library/Application Support`: the file is meant to be edited by
/// hand and kept in dotfiles alongside a niri config.
pub fn default_path() -> Option<PathBuf> {
    let home = std::env::var_os("HOME").filter(|home| !home.is_empty())?;
    Some(PathBuf::from(home).join(".config/elara/config.kdl"))
}

/// Loads the config at `path`.
///
/// On failure, returns niri's diagnostic, which points at the offending part of the file.
pub fn load(path: &Path) -> Result<Config, String> {
    Config::load(path).config.map_err(|err| format!("{err:?}"))
}

/// Loads the config at `path`, first creating it with the default contents if it is missing.
///
/// Returns the config and whether the file was created.
pub fn load_or_create(path: &Path) -> Result<(Config, bool), String> {
    let mut created = false;
    if !path.exists() {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)
                .map_err(|err| format!("could not create {}: {err}", parent.display()))?;
        }
        fs::write(path, DEFAULT_CONFIG)
            .map_err(|err| format!("could not create {}: {err}", path.display()))?;
        created = true;
    }
    load(path).map(|config| (config, created))
}

/// Names the parts of `config` that are set but have no effect on macOS.
pub fn ignored_sections(config: &Config) -> Vec<&'static str> {
    let default = Config::default();
    let mut ignored = Vec::new();

    if config.outputs != default.outputs {
        ignored.push("output (macOS sets display modes, scale and arrangement)");
    }
    if config.input.keyboard != default.input.keyboard {
        ignored.push("input.keyboard (macOS sets the keyboard layout and repeat rate)");
    }
    if config.input.touchpad != default.input.touchpad
        || config.input.mouse != default.input.mouse
        || config.input.trackpoint != default.input.trackpoint
    {
        ignored.push("input.touchpad, mouse and trackpoint (macOS sets pointer behaviour)");
    }
    if config.cursor != default.cursor {
        ignored.push("cursor (macOS draws the pointer)");
    }
    if !config.layer_rules.is_empty() {
        ignored.push("layer-rule (there are no layer-shell surfaces on macOS)");
    }
    if config.switch_events != default.switch_events {
        ignored.push("switch-events (lid and tablet-mode switches are not reported)");
    }
    if config.xwayland_satellite != default.xwayland_satellite {
        ignored.push("xwayland-satellite (there is no X11 on macOS)");
    }

    ignored
}

/// Notices when a file changes.
///
/// This checks the file's modification time and size when asked, rather than subscribing to
/// file system events: the main loop already wakes several times a second, the check is one
/// `stat` call, and it keeps working when an editor replaces the file instead of writing to it.
/// Files pulled in with `include` are not watched.
#[derive(Debug)]
pub struct ConfigWatcher {
    path: PathBuf,
    seen: Option<(SystemTime, u64)>,
}

impl ConfigWatcher {
    /// Starts watching `path`, taking its current state as already seen.
    pub fn new(path: PathBuf) -> Self {
        let seen = Self::stat(&path);
        Self { path, seen }
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    fn stat(path: &Path) -> Option<(SystemTime, u64)> {
        let metadata = fs::metadata(path).ok()?;
        Some((metadata.modified().ok()?, metadata.len()))
    }

    /// Returns whether the file changed since this was last called.
    ///
    /// A file that disappeared is not reported as changed: editors that save by replacing the
    /// file leave a moment where it does not exist, and the config in use stays valid.
    pub fn changed(&mut self) -> bool {
        match Self::stat(&self.path) {
            Some(current) if Some(current) != self.seen => {
                self.seen = Some(current);
                true
            }
            _ => false,
        }
    }
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use niri_config::{Action, Trigger};
    use smithay::input::keyboard::Keysym;

    use super::*;
    use crate::binds::find_bind;

    fn scratch_dir(name: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("elara-{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&dir);
        dir
    }

    #[test]
    fn default_config_parses_and_binds_macos_programs() {
        let config = default_config();

        let terminal = find_bind(
            &config,
            Trigger::Keysym(Keysym::t),
            niri_config::Modifiers::ALT,
        );
        assert_eq!(
            terminal.map(|bind| bind.action),
            Some(Action::Spawn(vec![
                "open".to_owned(),
                "-a".to_owned(),
                "Terminal".to_owned()
            ]))
        );
        // Linux-only startup programs are gone.
        assert!(config.spawn_at_startup.is_empty());
        assert!(ignored_sections(&config).is_empty());
    }

    #[test]
    fn default_config_differs_from_niri_only_in_marked_lines() {
        let niri = include_str!("../../../resources/default-config.kdl");
        let body = DEFAULT_CONFIG
            .split_once("// This config is in the KDL format")
            .map(|(_, rest)| format!("// This config is in the KDL format{rest}"))
            .expect("the header ends where niri's file begins");

        let niri_lines: Vec<&str> = niri.lines().collect();
        // Whether the line is in a comment that began with a marked ElaraWM line.
        let mut in_our_comment = false;
        for line in body.lines() {
            // Every line is niri's, or niri's commented out, or a marked ElaraWM line, or the
            // rest of the comment one begins, or the replacement that directly follows one.
            let uncommented = line.trim_start().strip_prefix("// ").unwrap_or(line);
            let is_niri = niri_lines
                .iter()
                .any(|theirs| *theirs == line || theirs.trim_start() == uncommented);
            if line.contains("ElaraWM:") {
                in_our_comment = true;
            } else if !line.starts_with("//") {
                in_our_comment = false;
            }
            let is_ours = in_our_comment
                || line.contains(r#"spawn "open" "-a""#)
                // The one section that is ElaraWM's own addition.
                || matches!(line, "overview {" | "    window-thumbnails");
            assert!(
                is_niri || is_ours,
                "unexpected line in the default config: {line}"
            );
        }
    }

    #[test]
    fn a_missing_config_is_created_with_the_default_contents() {
        let dir = scratch_dir("create");
        let path = dir.join("nested/config.kdl");

        let (config, created) = load_or_create(&path).unwrap();
        assert!(created);
        assert_eq!(fs::read_to_string(&path).unwrap(), DEFAULT_CONFIG);
        assert_eq!(config.binds, default_config().binds);

        // An existing file is left alone.
        fs::write(&path, "layout {\n gaps 40\n}\n").unwrap();
        let (config, created) = load_or_create(&path).unwrap();
        assert!(!created);
        assert_eq!(config.layout.gaps, 40.);

        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_broken_config_reports_where() {
        let dir = scratch_dir("broken");
        fs::create_dir_all(&dir).unwrap();
        let path = dir.join("config.kdl");
        fs::write(&path, "layout {\n gaps \"wide\"\n}\n").unwrap();

        let message = load(&path).unwrap_err();
        assert!(message.contains("gaps"), "{message}");

        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn ignored_sections_are_named() {
        let config = Config::parse_mem(
            r#"
            output "eDP-1" {
                scale 2.0
            }
            input {
                keyboard {
                    xkb {
                        layout "us,ru"
                    }
                }
                touchpad {
                    tap
                }
            }
            cursor {
                xcursor-size 48
            }
            layer-rule {
                match namespace="waybar"
                opacity 0.5
            }
            "#,
        )
        .unwrap();

        let ignored = ignored_sections(&config).join("\n");
        for section in [
            "output",
            "input.keyboard",
            "input.touchpad",
            "cursor",
            "layer-rule",
        ] {
            assert!(
                ignored.contains(section),
                "{section} missing from:\n{ignored}"
            );
        }
    }

    #[test]
    fn watcher_reports_each_change_once() {
        let dir = scratch_dir("watch");
        fs::create_dir_all(&dir).unwrap();
        let path = dir.join("config.kdl");
        fs::write(&path, "// one\n").unwrap();

        let mut watcher = ConfigWatcher::new(path.clone());
        assert!(!watcher.changed());

        fs::write(&path, "// two, longer\n").unwrap();
        assert!(watcher.changed());
        assert!(!watcher.changed());

        // Replacing the file, as editors do, counts; the gap in between does not.
        fs::remove_file(&path).unwrap();
        assert!(!watcher.changed());
        fs::write(&path, "// three, longer still\n").unwrap();
        assert!(watcher.changed());

        // Same size, later modification time.
        let later = SystemTime::now() + Duration::from_secs(5);
        fs::write(&path, "// 3hree, longer still\n").unwrap();
        fs::File::options()
            .write(true)
            .open(&path)
            .unwrap()
            .set_modified(later)
            .unwrap();
        assert!(watcher.changed());

        let _ = fs::remove_dir_all(&dir);
    }
}
